/**
 * Turns a Blockly workspace into a complete MicroPython file.
 *
 * The generated file always has the same shape, and every section is dropped
 * when it is empty, so a program never carries an import it does not use:
 *
 *     # Code automatically generated by PicoBlocks
 *     from machine import Pin, PWM      <- only the names actually used
 *     import time
 *
 *     pwm_15 = PWM(Pin(15))             <- one-time setup, deduplicated
 *
 *     def read_temperature():           <- helper functions
 *         ...
 *
 *     count = 0                         <- variables from the Variables category
 *
 *     Pin("LED", Pin.OUT).value(1)      <- body of the "on start" block
 *
 *     while True:                       <- body of the "forever" block
 *         ...
 */
import type * as Blockly from 'blockly';
import './control';
import './pins';
import './sensors';
import './sound';
import './text';
import {
  DEFAULT_GENERATOR_OPTIONS,
  MACHINE_NAMES,
  picoGenerator,
  type GeneratorOptions,
} from './generator';

export const HEADER_COMMENT = '# Code automatically generated by PicoBlocks';

export interface GeneratedProgram {
  /** The full MicroPython source, ending in a newline. */
  code: string;
  /** Pins this program drives with PWM, so Stop can silence them. */
  pwmPins: number[];
  /** False when the workspace has no enabled blocks that produce code. */
  hasCode: boolean;
}

export function generateProgram(
  workspace: Blockly.Workspace,
  options?: Partial<GeneratorOptions>,
): GeneratedProgram {
  const generator = picoGenerator;
  generator.options = { ...DEFAULT_GENERATOR_OPTIONS, ...options };
  generator.init(workspace);

  // Only `on start` and `forever` contribute code. Anything else left loose in
  // the workspace is an orphan; Blockly greys those blocks out.
  const topBlocks = workspace.getTopBlocks(true);
  const onStart = topBlocks.find((b) => b.type === 'on_start' && b.isEnabled());
  const forever = topBlocks.find((b) => b.type === 'forever' && b.isEnabled());

  const startCode = onStart ? (generator.blockToCode(onStart) as string) : '';
  const foreverCode = forever ? (generator.blockToCode(forever) as string) : '';

  const { imports, statements } = generator.takeDefinitions();
  const machineNames = MACHINE_NAMES.filter((name) =>
    generator.machineNames.has(name),
  );
  const importLines = [
    ...(machineNames.length ? [`from machine import ${machineNames.join(', ')}`] : []),
    ...[...generator.modules].sort().map((module) => `import ${module}`),
    ...imports.sort(),
  ];

  const sections: string[] = [
    [HEADER_COMMENT, ...importLines].join('\n'),
    [...generator.setup.values()].join('\n'),
    [...generator.helpers.values()].join('\n\n'),
    statements.join('\n'),
    startCode.trim(),
    foreverCode.trim(),
  ];

  const pwmPins = [...generator.pwmPins].sort((a, b) => a - b);
  generator.finishGeneration();

  const body = sections
    .map((section) => section.trim())
    .filter(Boolean)
    .join('\n\n');

  return {
    code: `${body}\n`,
    pwmPins,
    // An empty `forever` generates `while True: pass`, which is code but not a
    // program: Run and Save stay disabled until a block goes inside one of them.
    hasCode: Boolean(
      startCode.trim() || (forever && forever.getInputTargetBlock('DO')),
    ),
  };
}

/**
 * Code that puts the pins a program used back to a quiet, safe state. Sent
 * after Stop so an interrupted buzzer does not scream until the next run.
 */
export function quietPinsCode(pwmPins: number[]): string | null {
  if (!pwmPins.length) return null;
  return [
    'from machine import Pin',
    `for _pin in (${pwmPins.join(', ')},):`,
    '    Pin(_pin, Pin.OUT).value(0)',
  ].join('\n');
}
